1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"fmt"
17		"sort"
18	)
19	
20	// SnapshotFormatVersion is the only on-disk snapshot format understood.
21	const SnapshotFormatVersion = 1
22	
23	// SnapshotFile is the on-disk representation of one frozen lineage graph.
24	//
25	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
26	// verified against Graph on every read; Graph carries the complete graph.
27	type SnapshotFile struct {
28		FormatVersion int       `json:"formatVersion"`
29		ContentID     string    `json:"contentId"`
30		Graph         GraphFile `json:"graph"`
31	}
32	
33	// RootSourceChange reports that one dataset present in BOTH versions reaches a
34	// different set of root sources. OldRoots and NewRoots are sorted by name and
35	// never nil, so empty root sets encode as [] rather than null.
36	type RootSourceChange struct {
37		Dataset  string   `json:"dataset"`
38		OldRoots []string `json:"oldRoots"`
39		NewRoots []string `json:"newRoots"`
40	}
41	
42	// CompareReport is the deterministic, read-only diff of two snapshots read in
43	// the fixed direction old -> new.
44	//
45	// NewDatasets and RemovedDatasets list nodes present on only one side.
46	// ChangedDatasets lists datasets present on both sides whose direct upstream
47	// set actually changed. AddedRelations and RemovedRelations list every
48	// directed edge present on only one side, including edges that vanish because
49	// one endpoint node was removed. RootSourceChanges covers only datasets common
50	// to both versions whose reachable root set differs; added or removed datasets
51	// never appear there.
52	type CompareReport struct {
53		NewDatasets       []string           `json:"newDatasets"`
54		RemovedDatasets   []string           `json:"removedDatasets"`
55		ChangedDatasets   []string           `json:"changedDatasets"`
56		AddedRelations    []Relation         `json:"addedRelations"`
57		RemovedRelations  []Relation         `json:"removedRelations"`
58		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
59	}
60	
61	// contentIDPrefix names the hash algorithm used for content addressing.
62	const contentIDPrefix = "sha256:"
63	
64	// graphAdjacencyFromFile builds the validated, normalized parent adjacency
65	// directly from a parsed graph file. It rejects empty names, duplicate
66	// datasets, and references to upstreams that are not declared; cycle checking
67	// is the caller's responsibility (via validateAcyclic) so the reported reason
68	// stays specific.
69	func graphAdjacencyFromFile(gf GraphFile) (adjacency, error) {
70		adj := make(adjacency, len(gf.Datasets))
71		for _, ds := range gf.Datasets {
72			if ds.Name == "" {
73				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
74			}
75			if _, exists := adj[ds.Name]; exists {
76				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
77			}
78			adj[ds.Name] = uniqueSorted(ds.Upstreams)
79		}
80		for name, parents := range adj {
81			for _, parent := range parents {
82				if _, ok := adj[parent]; !ok {
83					return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
84				}
85			}
86		}
87		return adj, nil
88	}
89	
90	// canonicalGraph serializes the graph's semantics deterministically: datasets
91	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
92	// JSON with no insignificant whitespace. Two semantically equal graphs always
93	// produce identical bytes.
94	func canonicalGraph(adj adjacency) ([]byte, error) {
95		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
96		return json.Marshal(gf)
97	}
98	
99	// computeContentID returns the content identifier of the graph bytes:
100	// "sha256:" followed by the lowercase hex SHA-256 digest.
101	func computeContentID(canonical []byte) string {
102		sum := sha256.Sum256(canonical)
103		return contentIDPrefix + hex.EncodeToString(sum[:])
104	}
105	
106	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
107	// version 1 and the matching content identifier. It does not mutate graph. The
108	// returned document and its serialized bytes depend only on graph semantics.
109	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
110		if err := ValidateGraph(graph); err != nil {
111			return nil, err
112		}
113		adj, err := graphAdjacency(graph)
114		if err != nil {
115			return nil, err
116		}
117		canonical, err := canonicalGraph(adj)
118		if err != nil {
119			return nil, err
120		}
121		return &SnapshotFile{
122			FormatVersion: SnapshotFormatVersion,
123			ContentID:     computeContentID(canonical),
124			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
125		}, nil
126	}
127	
128	// MarshalSnapshot serializes a snapshot the same way for every save: indented
129	// JSON keyed by struct field order, terminated by a single newline.
130	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
131		var buf bytes.Buffer
132		enc := json.NewEncoder(&buf)
133		enc.SetIndent("", "  ")
134		enc.SetEscapeHTML(false)
135		if err := enc.Encode(snap); err != nil {
136			return nil, err
137		}
138		return buf.Bytes(), nil
139	}
140	
141	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
142	// can distinguish "field absent" from "field present with a zero value"
143	// (e.g. a missing formatVersion must be rejected rather than read as 0).
144	type rawSnapshot struct {
145		FormatVersion json.RawMessage `json:"formatVersion"`
146		ContentID     json.RawMessage `json:"contentId"`
147		Graph         json.RawMessage `json:"graph"`
148	}
149	
150	// isJSONNull reports whether a raw JSON value is the literal null.
151	func isJSONNull(raw json.RawMessage) bool {
152		return string(bytes.TrimSpace(raw)) == "null"
153	}
154	
155	// ParseSnapshot parses and strictly validates one snapshot document: required
156	// fields must be present and well-typed, the format version must be supported,
157	// the embedded graph must be structurally valid (no empty names, duplicate
158	// datasets, missing upstreams, or cycles), and the content identifier must
159	// correspond exactly to the graph. A tampered, corrupt, or otherwise invalid
160	// snapshot is rejected, so a bad file can never be trusted as a version.
161	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
162		var raw rawSnapshot
163		if err := json.Unmarshal(data, &raw); err != nil {
164			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
165		}
166		if len(raw.FormatVersion) == 0 {
167			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
168		}
169		if len(raw.ContentID) == 0 {
170			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
171		}
172		if len(raw.Graph) == 0 {
173			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
174		}
175		// An explicit JSON null is present-but-untyped and must not be silently
176		// treated as a zero value (in particular, graph:null must not read as an
177		// empty graph).
178		if isJSONNull(raw.FormatVersion) {
179			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
180		}
181		if isJSONNull(raw.ContentID) {
182			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
183		}
184		if isJSONNull(raw.Graph) {
185			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
186		}
187	
188		var version int
189		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
190			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
191		}
192		if version != SnapshotFormatVersion {
193			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
194		}
195	
196		var contentID string
197		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
198			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
199		}
200		if contentID == "" {
201			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
202		}
203	
204		var gf GraphFile
205		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
206			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
207		}
208		adj, err := graphAdjacencyFromFile(gf)
209		if err != nil {
210			return nil, err
211		}
212		if err := validateAcyclic(adj); err != nil {
213			return nil, err
214		}
215	
216		canonical, err := canonicalGraph(adj)
217		if err != nil {
218			return nil, err
219		}
220		if want := computeContentID(canonical); contentID != want {
221			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
222		}
223	
224		return &SnapshotFile{
225			FormatVersion: version,
226			ContentID:     contentID,
227			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
228		}, nil
229	}
230	
231	// CompareSnapshots returns the fixed-direction diff from old to new. Both
232	// inputs are assumed to have passed ParseSnapshot; the report is fully
233	// deterministic and identical for semantically identical comparisons.
234	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
235		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
236		newAdj := adjacencyFromValidFile(newSnap.Graph)
237	
238		added, removed := diffRelations(oldAdj, newAdj)
239	
240		var newNodes, removedNodes, changedNodes []string
241		for name := range newAdj {
242			if oldParents, ok := oldAdj[name]; !ok {
243				newNodes = append(newNodes, name)
244			} else if !stringSliceEqual(oldParents, newAdj[name]) {
245				changedNodes = append(changedNodes, name)
246			}
247		}
248		for name := range oldAdj {
249			if _, ok := newAdj[name]; !ok {
250				removedNodes = append(removedNodes, name)
251			}
252		}
253		sort.Strings(newNodes)
254		sort.Strings(removedNodes)
255		sort.Strings(changedNodes)
256	
257		common := make([]string, 0)
258		for name := range oldAdj {
259			if _, ok := newAdj[name]; ok {
260				common = append(common, name)
261			}
262		}
263		sort.Strings(common)
264	
265		rootChanges := make([]RootSourceChange, 0)
266		for _, name := range common {
267			oldRoots := rootSources(name, oldAdj)
268			newRoots := rootSources(name, newAdj)
269			if !stringSliceEqual(oldRoots, newRoots) {
270				rootChanges = append(rootChanges, RootSourceChange{
271					Dataset:  name,
272					OldRoots: oldRoots,
273					NewRoots: newRoots,
274				})
275			}
276		}
277	
278		return &CompareReport{
279			NewDatasets:       orEmptyStrings(newNodes),
280			RemovedDatasets:   orEmptyStrings(removedNodes),
281			ChangedDatasets:   orEmptyStrings(changedNodes),
282			AddedRelations:    orEmptyRelations(added),
283			RemovedRelations:  orEmptyRelations(removed),
284			RootSourceChanges: rootChanges,
285		}
286	}
287	
288	// adjacencyFromValidFile builds normalized parent adjacency from an already
289	// validated graph file.
290	func adjacencyFromValidFile(gf GraphFile) adjacency {
291		adj := make(adjacency, len(gf.Datasets))
292		for _, ds := range gf.Datasets {
293			adj[ds.Name] = uniqueSorted(ds.Upstreams)
294		}
295		return adj
296	}
297	
298	// rootSources returns the root datasets reachable from node by following
299	// direct upstream edges. A node without upstreams is itself a root and its own
300	// source, so it is included. Nodes reached by more than one path count once.
301	// The result is sorted by name and never nil.
302	func rootSources(node string, adj adjacency) []string {
303		visited := make(map[string]bool)
304		var roots []string
305		var walk func(string)
306		walk = func(current string) {
307			if visited[current] {
308				return
309			}
310			visited[current] = true
311			parents := adj[current]
312			if len(parents) == 0 {
313				roots = append(roots, current)
314				return
315			}
316			for _, parent := range parents {
317				walk(parent)
318			}
319		}
320		walk(node)
321		sort.Strings(roots)
322		return orEmptyStrings(roots)
323	}
324	
325	func orEmptyStrings(s []string) []string {
326		if s == nil {
327			return []string{}
328		}
329		return s
330	}
331	
332	func orEmptyRelations(r []Relation) []Relation {
333		if r == nil {
334			return []Relation{}
335		}
336		return r
337	}
