}

func TestCLIHelpMentionsTrace(t *testing.T) {
	stdout, _, exit := captureStdout(t, func() int { return run([]string{"help"}) })
	if exit != 0 {
		t.Fatalf("help exit = %d", exit)
	}
	if !strings.Contains(stdout, "trace") {
		t.Errorf("help missing trace:\n%s", stdout)
	}
}

